    Returns the stack (bottom to top) after all lines have been processed.
    Definitions and stack contents carry over from one line to the next.
    """
    if isinstance(input_data, str):
        input_data = [input_data]

    stack = []
    definitions = {}
    state = "normal"       # one of: normal, name, definition
    current_name = None
    current_body = []

    for line in input_data:
        for raw_token in line.split():
            token = raw_token.lower()

            if state == "name":
                # Numbers cannot be used as names for new words.
                if _is_number(token):
                    raise ValueError("illegal operation")
                current_name = token
                state = "definition"
                continue

            if state == "definition":
                if token == ";":
                    definitions[current_name] = current_body
                    current_body = []
                    current_name = None
                    state = "normal"
                else:
                    current_body.extend(_expand(token, definitions))
                continue

            # Normal mode.
            if token == ":":
                state = "name"
            elif token == ";":
                raise ValueError("illegal operation")
            else:
                word = token if _is_number(token) else token.lower()
                _execute(word, stack, definitions)

    return stack
